import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let m = conc.Mutex(0)
    let cv = conc.Cond(m)
    let sem = conc.Semaphore(1)
    let ch: conc.Channel<Int64> = conc.channel(2)
    scope {
        let t = task effect io {
            let _ = m.set(1)
            let _ = sem.release()
            let _ = ch.close()
        }
        let _ = t.await()
    }
    sem.acquire()
    cv.wait(|v| v > 0)
    ch.send(1)
    let a = ch.receive()
    let _ = a
    let b = ch.trySend(2)
    let c = ch.tryReceive()
    let _ = b
    let _ = c
    return Ok(())
}
